  "summary": "The code contains 5 identified issues, primarily focusing on performance bottlenecks due to synchronous-like shell execution and maintainability concerns. The most critical finding is the lack of rate limiting on a resource-intensive shell-executing endpoint. The code has been refactored to include constants, environment variables, and a basic cache mechanism.",
  "fixed_code": "const express = require('express');
const { execFile } = require('child_process');
const path = require('path');
const rateLimit = require('express-rate-limit');

const app = express();
const UPLOADS = path.resolve(__dirname, 'uploads');
const PORT = process.env.PORT || 3000;
const MIN_GIT_LOG = 1;
const MAX_GIT_LOG = 100;

let cache = { data: null, timestamp: 0 };
const CACHE_TTL = 60000;

const limiter = rateLimit({ windowMs: 60000, max: 50 });

/**
 * @route GET /log
 * @desc Returns recent git commits
 */
app.get('/log', limiter, (req, res) => {
    const count = Number.parseInt(req.query.n, 10);
    if (!Number.isInteger(count) || count < MIN_GIT_LOG || count > MAX_GIT_LOG) {
        return res.status(400).json({ error: 'n must be 1-100' });
    }

    const now = Date.now();
    if (cache.data && (now - cache.timestamp < CACHE_TTL)) {
        return res.json({ commits: cache.data.slice(0, count) });
    }

    execFile('git', ['log', '--oneline', '-n', String(MAX_GIT_LOG)], { timeout: 5000 }, (err, stdout) => {
        if (err) return res.status(500).json({ error: 'git failed' });
        cache.data = stdout.split('\n').filter(Boolean);
        cache.timestamp = Date.now();
        res.json({ commits: cache.data.slice(0, count) });
    });
});

/**
 * @route GET /files/:name
 * @desc Serves static files from uploads directory
 */
app.get('/files/:name', (req, res) => {
    const full = path.resolve(UPLOADS, req.params.name);
    if (!full.startsWith(UPLOADS + path.sep)) return res.sendStatus(400);
    res.sendFile(full);
});

app.listen(PORT, () => console.log(`Server running on port ${PORT}`));"
}
